mapper.select:
WITH requested_session_ids(id) AS ( VALUES
(#{sessionId})
), target_sessions AS ( SELECT session.id, session.scene_code FROM requested_session_ids requested INNER JOIN ai_session session ON session.id = requested.id WHERE session.user_id = #{userId} ) SELECT run.id, run.session_id, run.scene_code, run.status, run.active_flag, run.updated_at FROM target_sessions session INNER JOIN ai_agent_run run ON run.id = ( SELECT candidate.id FROM ai_agent_run candidate WHERE candidate.user_id = #{userId} AND candidate.session_id = session.id AND candidate.scene_code = session.scene_code ORDER BY candidate.active_flag DESC, candidate.updated_at DESC, candidate.id DESC LIMIT 1 )
